import numpy as np

def objective(b, c):
    if c >= 1 or b <= 0:
        return float('inf')
    a = (b - 1 - b*c - b**2*c) / (b * (1 - c))
    if a <= 0:
        return float('inf')
    d = 1 / (a * b * c)
    return a + b + c + d

best_f = float('inf')
best_x = None

# Grid search
for b_val in np.linspace(0.1, 50, 500):
    for c_val in np.linspace(0.01, 0.99, 500):
        f = objective(b_val, c_val)
        if f < best_f:
            best_f = f
            best_x = (b_val, c_val)

print(f"Best f: {best_f} at {best_x}")

# Also check the case b=c for completeness (though c must be < 1)
def obj_bc(b):
    if b >= 1: return float('inf')
    a = (b - 1 - b**2 - b**3) / (b * (1 - b))
    # simplify a: (b - 1 - b^2(1+b)) / (b(1-b)) = (b-1 - b^2(1+b)) / (b(1-b))
    # actually (b-1-b^2-b^3)/(b-b^2) = (b-1-b^2-b^3)/b(1-b)
    # but we need a > 0.
    # a = (b-1-b^2-b^3)/(b(1-b)). For b < 1, 1-b > 0, so we need b-1-b^2-b^3 > 0.
    # For b > 0, b-1-b^2-b^3 is always < 0.
    # Thus b=c cannot have a > 0.
    return float('inf')

